CompositionLocalProvider(LocalMonarchStatusRegistry provides tickets) {
    Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
        MonarchStatusBadge(status = "open")
        MonarchStatusBadge(status = "waiting", variant = MonarchStatusBadgeVariant.Outline)
    }
}

examples.setup:
val tickets = remember {
    MonarchStatusRegistry(
        mapOf(
            "open" to MonarchStatusDefinition("Open", MonarchTone.Info),
            "waiting" to MonarchStatusDefinition("Waiting on customer", MonarchTone.Warning),
        ),
    )
}
